=== README.md
# network

Shared network for the staging environment. Tags come from the platform team's `terraform-labels`
module, which every configuration reuses.
=== main.tf
module "labels" {
  source = "git::https://git.example.com/platform/terraform-labels.git"

  service     = "network"
  environment = var.environment
}
=== providers.tf
provider "aws" {
  region = var.region

  default_tags {
    tags = module.labels.tags
  }
}
=== variables.tf
variable "region" {
  type    = string
  default = "eu-north-1"
}

variable "environment" {
  type    = string
  default = "staging"
}
=== versions.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }

  backend "s3" {
    bucket       = "network-terraform-state"
    key          = "network/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }
}

