input.command:
sed -i 's|version = ">= 4.0"|version = "~> 6.0"|' versions.tf
cat >> main.tf <<'EOF'

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 6.0"

  name = "${module.labels.tags["Name"] != null ? module.labels.tags["Name"] : "network"}-${var.environment}"
  cidr = var.vpc_cidr

  azs             = ["${var.region}a", "${var.region}b"]
  private_subnets = var.private_subnet_cidrs

  tags = module.labels.tags
}
EOF
sed -i 's|^  name = .*|  name = "network-${var.environment}"|' main.tf
cat >> variables.tf <<'EOF'

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "private_subnet_cidrs" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}
EOF
cat >> outputs.tf <<'EOF'
output "vpc_id" {
  value = module.vpc.vpc_id
}

output "private_subnet_ids" {
  value = module.vpc.private_subnets
}
EOF
terraform fmt -check; terraform init -backend=false 2>&1 | tail -5; terraform validate 2>&1 | tail -8

